1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.time.LocalDate;
14	import java.util.Collection;
15	import java.util.List;
16	
17	/**
18	 * Maps Owner & OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
24	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
25	    @Mapping(target = "householdId", expression = "java(org.springframework.samples.petclinic.util.Household.idFor(owner))")
26	    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
27	    @Mapping(target = "membershipLevel", expression = "java(Math.min(4, 1 + (owner.getEmail() != null ? 1 : 0) + (Integer.valueOf(0).equals(owner.getNamesakeCount()) ? 1 : 0) + (java.time.temporal.ChronoUnit.DAYS.between(owner.getRegistrationDate(), java.time.LocalDate.now()) > 365 ? 1 : 0)))")
28	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.util.CustomerCode.region(owner.getCustomerCode()))")
29	    @Mapping(target = "contactPreference", expression = "java(owner.getEmail() != null ? \"EMAIL\" : \"PHONE\")")
30	    @Mapping(target = "ageBand", expression = "java(org.springframework.samples.petclinic.util.AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate()))")
31	    @Mapping(target = "identityKey", expression = "java(org.springframework.samples.petclinic.util.IdentityKey.of(owner))")
32	    @Mapping(target = "checkDigit", expression = "java(org.springframework.samples.petclinic.util.CheckDigit.luhn(owner.getCustomerCode()))")
33	    @Mapping(target = "telephoneDisplay", expression = "java(org.springframework.samples.petclinic.util.TelephoneDisplay.of(owner.getTelephone()))")
34	    OwnerDto toOwnerDto(Owner owner);
35	
36	    Owner toOwner(OwnerDto ownerDto);
37	
38	    @Mapping(target = "id", ignore = true)
39	    @Mapping(target = "pets", ignore = true)
40	    @Mapping(target = "registrationDate", source = "registrationDate", qualifiedByName = "defaultRegistrationDate")
41	    Owner toOwner(OwnerFieldsDto ownerDto);
42	
43	    /** Default a missing registration date to the server's current date, then roll
44	     *  the effective date forward onto a business day. */
45	    @Named("defaultRegistrationDate")
46	    default LocalDate defaultRegistrationDate(LocalDate registrationDate) {
47	        return org.springframework.samples.petclinic.util.BusinessDay.rollForward(
48	            registrationDate == null ? LocalDate.now() : registrationDate);
49	    }
50	
51	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
52	
53	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
54	
55	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
56	        OwnerPageDto ownerPageDto = new OwnerPageDto();
57	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
58	        ownerPageDto.setPage(ownerPage.getNumber());
59	        ownerPageDto.setSize(ownerPage.getSize());
60	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
61	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
62	        return ownerPageDto;
63	    }
64	}
